  readonly predecessorRemainingEscrowBillingVectorDigest: string;
  readonly resultingRemainingEscrowBillingVectorDigest: string;
  readonly correctionDeltaBillingVectorDigest: string;
  readonly correctionDeltaFitsRetainedEscrow: true;
  readonly noPreviouslyReleasedBalanceIsConsumed: true;
  readonly newReservationsFrozenBeforeCorrectionApplication: true;
  readonly provesCorrectionLeaseConsumesCurrentChildEscrowCursorAndSequenceExactlyOnce: true;
  readonly provesProvisionalSettlementApplyEqualsPredecessorCurrentProvisionalSettlementApply: true;
  readonly provesCorrectionDeltaSubtractsFromCurrentRemainingEscrowWithoutUnderflow: true;
  readonly childEscrowAndBalanceCursorCasCommittedAtomically: true;
