interface RuntimeRouteSequenceCursorBase<
  P extends PhysicalAttemptRetrySafetySubjectV8 = PhysicalAttemptRetrySafetySubjectV8,
> extends ReceiptRef {
  readonly writerLease: ReferenceMonitorWriterLeaseReceipt;
  readonly writerEpoch: number;
  readonly runtimeRouteFenceLease: RuntimeRouteFenceLeaseReceipt;
  readonly ingressAttemptId: string;
  readonly selectedSequenceDigest: string;
  readonly predecessorCursor?: RuntimeRouteSequenceCursorReceipt<P>;
  readonly expectedRevision: number;
  readonly revision: number;
  readonly nextOrdinal: number;
}

type RuntimeRouteReadyCursorReceipt<
  P extends PhysicalAttemptRetrySafetySubjectV8 = PhysicalAttemptRetrySafetySubjectV8,
> = RuntimeRouteSequenceCursorBase<P> &
  (
    | {
        readonly cursorCause: "initial";
        readonly state: "ready";
        readonly predecessorCursor?: never;
        readonly lastAttemptLease?: never;
        readonly lastAttemptTerminal?: never;
        readonly zeroAttemptTerminal?: never;
      }
    | {
        readonly cursorCause: "attempt_terminal_advance";
        readonly state: "ready";
        readonly predecessorCursor: RuntimeRouteAttemptInFlightCursorReceipt<P>;
        readonly lastAttemptLease: RuntimeUpstreamAttemptLeaseReceipt;
        readonly lastAttemptTerminal: Extract<PhysicalAttemptTerminalReceipt<P>, { readonly phase: "runtime" }> & {
          readonly resultingCursorState: "ready";
        };
        readonly automaticRetryAdvance: AutomaticRetryAdvanceEdgeReceiptV8<P>;
        readonly zeroAttemptTerminal?: never;
        readonly provesPredecessorLeaseTerminalEdgeAndOrdinalEqual: true;
      }
  );

interface RuntimeRouteAttemptInFlightCursorReceipt<
  P extends PhysicalAttemptRetrySafetySubjectV8 = PhysicalAttemptRetrySafetySubjectV8,
> extends RuntimeRouteSequenceCursorBase<P> {
  readonly cursorCause: "attempt_lease";
  readonly state: "attempt_in_flight";
  readonly predecessorCursor: RuntimeRouteReadyCursorReceipt<P>;
  readonly lastAttemptLease: RuntimeUpstreamAttemptLeaseReceipt;
  readonly lastAttemptTerminal?: never;
  readonly zeroAttemptTerminal?: never;
}

type RuntimeRouteTerminalCursorReceipt<
  P extends PhysicalAttemptRetrySafetySubjectV8 = PhysicalAttemptRetrySafetySubjectV8,
> = RuntimeRouteSequenceCursorBase<P> &
  (
    | {
        readonly cursorCause: "attempt_terminal";
        readonly state: "terminal";
        readonly predecessorCursor: RuntimeRouteAttemptInFlightCursorReceipt<P>;
        readonly lastAttemptLease: RuntimeUpstreamAttemptLeaseReceipt;
        readonly lastAttemptTerminal: Extract<PhysicalAttemptTerminalReceipt<P>, { readonly phase: "runtime" }> & {
          readonly resultingCursorState: "terminal";
        };
        readonly zeroAttemptTerminal?: never;
      }
    | {
        readonly cursorCause: "zero_attempt_terminal";
        readonly state: "terminal";
        readonly predecessorCursor: Extract<RuntimeRouteReadyCursorReceipt<P>, { readonly cursorCause: "initial" }>;
        readonly lastAttemptLease?: never;
        readonly lastAttemptTerminal?: never;
        readonly zeroAttemptTerminal: RuntimeZeroAttemptTerminalReceipt;
      }
  );

type RuntimeRouteSequenceCursorReceipt<
  P extends PhysicalAttemptRetrySafetySubjectV8 = PhysicalAttemptRetrySafetySubjectV8,
> =
  | RuntimeRouteReadyCursorReceipt<P>
  | RuntimeRouteAttemptInFlightCursorReceipt<P>
  | RuntimeRouteTerminalCursorReceipt<P>;

