  readonly provesAttemptIntentDescriptorPredecessorRouteFenceEnvelopeOrdinalAndSubjectEqual: true;
  readonly provesOptionalServerAuthSendClosureEqualsDescriptorCredentialClosure: true;
  readonly commitTokenDigest: string;
  readonly grantsConditionalSendAuthorityOnly: true;
  readonly competesWithDescriptorAbortOnExactDescriptorSubjectAndSingleSuccessorCas: true;
