type LocalPreloadTerminalReceipt = ReceiptRef &
  LocalPreloadTerminalBase &
  (
    | {
        readonly intentState: "present";
        readonly effectIntent: LocalPreloadEffectIntentReceipt;
        readonly preIntentClosure?: never;
        readonly outcome: "loaded";
        readonly loadedArtifactDigest: string;
        readonly loadedArtifactFileIdentityDigest: string;
        readonly modelLoadGeneration: number;
        readonly measuredResidentBytes: number;
        readonly permitsLocalComputeEvidence: true;
        readonly provesEffectIntentPredecessorAndLeaseEqual: true;
      }
    | {
        readonly intentState: "present";
        readonly effectIntent: LocalPreloadEffectIntentReceipt;
        readonly preIntentClosure?: never;
        readonly outcome: "oom" | "cancelled" | "failed" | "deadline" | "route_changed_to_cloud_or_lan";
        readonly loadedArtifactDigest?: never;
        readonly loadedArtifactFileIdentityDigest?: never;
        readonly permitsLocalComputeEvidence: false;
        readonly provesEffectIntentPredecessorAndLeaseEqual: true;
      }
    | {
        readonly intentState: "absent";
        readonly effectIntent?: never;
        readonly preIntentClosure: PreIntentLeaseClosureReceipt<LocalPreloadLeaseReceipt>;
        readonly outcome:
          | "failed_before_intent"
          | "cancelled_before_intent"
          | "hard_stopped_before_intent"
          | "deadline_before_intent"
          | "lease_expired_before_intent"
          | "route_changed_before_intent";
        readonly loadedArtifactDigest?: never;
        readonly loadedArtifactFileIdentityDigest?: never;
        readonly permitsLocalComputeEvidence: false;
        readonly provesNoEffectIntentModelLoadByteOrProcessInputExistsForPreloadLease: true;
      }
  );

