type CandidateRightsForBillingV9<B extends CandidateBillingReceipt> =
  B extends PricedCandidateBillingReceipt
    ? CandidateRightsGrantReceipt
    : B extends CustomUnknownCandidateBillingReceipt
      ? B["customRights"]
      : B extends OfficialUnknownCandidateBillingReceipt
        ? B["officialRights"]
        : never;

type ConformancePolicyKindForBillingV9<B extends CandidateBillingReceipt> =
  B extends PricedCandidateBillingReceipt
    ? "priced_candidate"
    : B extends CustomUnknownCandidateBillingReceipt
      ? "externally_metered_unknown_custom"
      : B extends OfficialUnknownCandidateBillingReceipt
        ? "externally_metered_unknown_official"
        : never;

