interface ActualAttemptReportBase {
  readonly selectedSequenceDigest: string;
  readonly actualSentSequenceDigest: string;
  readonly sentPhysicalAttemptLeaseRefs: readonly ReceiptRef[];
  readonly ledgerSentEntryRefs: readonly ReceiptRef[];
  readonly terminalAttemptRefs: readonly ReceiptRef[];
  readonly authoritativeLedgerRange: AuthoritativeLedgerRangeReceipt;
  readonly actualPerComponentUnitAmountDigest: string;
  readonly reportRevision: number;
  readonly provesAllBoundLedgerSentEntriesIncludedExactlyOnce: true;
  readonly provesDisclosedSequencePrefixOrAllowedMemberSequence: true;
  readonly provesCompleteThroughLedgerHighWatermark: true;
}

type ActualAttemptReportReceipt = ReceiptRef & ActualAttemptReportBase &
  (
    | ({
        readonly reportKind: "conformance";
        readonly validationJourneyId: string;
        readonly round: "staged" | "live";
        readonly ingressAttemptId: string;
        readonly sessionId?: never;
        readonly turnOrdinal?: never;
        readonly fundingDecisionRefs: readonly [];
      } &
        (
          | {
              readonly conformanceAdmissionDecision: Extract<
                ConformanceAdmissionDecisionReceipt,
                { readonly kind: "priced_authorization" }
              >;
              readonly authorizationDisclosure: Extract<
                AuthorizationDisclosureReceipt,
                { readonly disclosureKind: "conformance_priced" }
              >;
            }
          | {
              readonly conformanceAdmissionDecision: Extract<
                ConformanceAdmissionDecisionReceipt,
                { readonly kind: "externally_metered_unknown_custom" }
              >;
              readonly authorizationDisclosure: Extract<
                AuthorizationDisclosureReceipt,
                { readonly disclosureKind: "conformance_externally_metered_unknown_custom" }
              >;
            }
          | {
              readonly conformanceAdmissionDecision: Extract<
                ConformanceAdmissionDecisionReceipt,
                { readonly kind: "externally_metered_unknown_official" }
              >;
              readonly authorizationDisclosure: Extract<
                AuthorizationDisclosureReceipt,
                { readonly disclosureKind: "conformance_externally_metered_unknown_official" }
              >;
            }
        ))
    | {
        readonly reportKind: "runtime_inference";
        readonly authorizationDisclosure: Extract<AuthorizationDisclosureReceipt, { readonly disclosureKind: "runtime" }>;
        readonly logicalCallId: string;
        readonly ingressAttemptId: string;
        readonly sessionId?: never;
        readonly turnOrdinal?: never;
        readonly fundingDecisionRefs: NonEmptyReadonly<InferenceFundingDecisionReceipt>;
      }
    | {
        readonly reportKind: "fallback_inference";
        readonly authorizationDisclosure: Extract<AuthorizationDisclosureReceipt, { readonly disclosureKind: "fallback" }>;
        readonly logicalCallId: string;
        readonly ingressAttemptId: string;
        readonly sessionId?: never;
        readonly turnOrdinal?: never;
        readonly fundingDecisionRefs: NonEmptyReadonly<InferenceFundingDecisionReceipt>;
        readonly fallbackAdmission: FallbackAdmissionReceipt;
      }
    | {
        readonly reportKind: "execution_session";
        readonly authorizationDisclosure: Extract<
          AuthorizationDisclosureReceipt,
          { readonly disclosureKind: "execution_session" }
        >;
        readonly logicalCallId: string;
        readonly ingressAttemptId: string;
        readonly sessionId: string;
        readonly turnOrdinal: number;
        readonly fundingDecisionRefs: readonly [];
        readonly executionSpendDecision:
          | ExecutionSessionStartSpendDecisionReceipt
          | ExecutionSpendDecisionReceipt;
      }
    | {
        readonly reportKind: "execution_tool";
        readonly authorizationDisclosure: Extract<AuthorizationDisclosureReceipt, { readonly disclosureKind: "execution_tool" }>;
        readonly logicalCallId: string;
        readonly ingressAttemptId: string;
        readonly sessionId: string;
        readonly turnOrdinal: number;
        readonly logicalToolInvocationId: string;
        readonly fundingDecisionRefs: readonly [];
        readonly executionSpendDecision: ExecutionSpendDecisionReceipt;
        readonly toolConsent: ExecutionToolConsentReceipt;
      }
  ) &
  (
    | {
        readonly revisionKind: "initial";
        readonly reportRevision: 0;
        readonly predecessorReport?: never;
        readonly correctionCommit?: never;
        readonly supersedesReportDigest?: never;
      }
    | {
        readonly revisionKind: "corrected";
        readonly predecessorReport: ActualAttemptReportReceipt;
        readonly correctionCommit: AuthoritativeLedgerCorrectionReceipt;
        readonly supersedesReportDigest: string;
      }
  );

