type CapabilityReasoningSupportV2 =
  | {
      readonly kind: "none";
      readonly reasoningTokenOrTraceControlVerified: false;
      readonly rawReasoningConformanceEvidence?: never;
    }
  | {
      readonly kind: "native_reasoning" | "verified_deliberative_decomposition";
      readonly reasoningTokenOrTraceControlVerified: true;
      readonly rawReasoningConformanceEvidence: RawResponseInventoryReceipt;
      readonly maximumVerifiedReasoningBudget: number;
    };

type CapabilityStructuredOutputSupportV2 =
  | {
      readonly kind: "none_or_json_object_only";
      readonly jsonSchemaSupported: false;
      readonly strictSchemaConformanceEvidence?: never;
    }
  | {
      readonly kind: "json_schema_strict";
      readonly jsonSchemaSupported: true;
      readonly strictSchemaEnforced: true;
      readonly malformedAndAdversarialSchemaFixtureSetDigest: string;
      readonly strictSchemaConformanceEvidence: RawResponseInventoryReceipt;
    };

type CapabilityMarginalSpendClassV2 =
  | {
      readonly kind: "owned_capacity";
      readonly currentOwnedCapacityProof: NoNewSpendProofReceipt;
      readonly automaticOveragePossible: false;
    }
  | {
      readonly kind: "verified_low_cost";
      readonly currentPriceEvidenceDigest: string;
      readonly comparisonSetDigest: string;
      readonly maximumMarginalCostVectorDigest: string;
      readonly automaticOveragePossible: boolean;
    }
  | {
      readonly kind: "not_cost_qualified";
      readonly currentOwnedCapacityProof?: never;
      readonly currentPriceEvidenceDigest?: never;
    };

interface CapabilityReceiptBase {
  readonly conformanceJourneyCompletion: ConformanceJourneyCompletionReceipt;
  readonly liveConformanceResult: LiveConformanceResultReceipt;
  readonly resourceSubjectDigest: string;
  readonly computeBoundaryCore: ReceiptRef;
  readonly effectiveRoute: ReceiptRef;
  readonly modelIdentity: ReceiptRef;
  readonly endpointIdentityDigest: string;
  readonly connectorRevision: number;
  readonly adapterArtifact: ReceiptRef;
  readonly observedModelIdentityDigest: string;
  readonly rawCapabilityEvidenceInventory: NonEmptyReadonly<RawResponseInventoryReceipt>;
  readonly inputModalities: NonEmptyReadonly<"text" | "image" | "audio">;
  readonly outputModalities: NonEmptyReadonly<"text" | "image" | "audio" | "structured_json">;
  readonly maximumVerifiedInputTokens: number;
  readonly maximumVerifiedOutputTokens: number;
  readonly usageReporting: "authoritative" | "advisory" | "absent";
  readonly cacheSemantics: "verified" | "unsupported" | "unknown";
  readonly reasoningSupport: CapabilityReasoningSupportV2;
  readonly structuredOutputSupport: CapabilityStructuredOutputSupportV2;
  readonly marginalSpendClass: CapabilityMarginalSpendClassV2;
  readonly visionInputVerified: boolean;
  readonly capabilityAxesAndLimitsDerivedOnlyFromRawCurrentModelConformanceEvidence: true;
}

type CapabilityReceipt = ReceiptRef &
  CapabilityReceiptBase &
  (
    | {
        readonly conversationProfile: "plain_dialog";
        readonly verifiedOperations: readonly ["chat"];
        readonly streamingVerified: true;
        readonly cancellationVerified: true;
        readonly textInputOutputVerified: true;
        readonly toolDefinitionsSupported: false;
        readonly toolChoiceSupported: false;
        readonly toolResultContinuationSupported: false;
        readonly permitsConversationReady: true;
        readonly forbidsToolRoundtripExecutionAndToolDependentWorkflow: true;
      }
    | {
        readonly conversationProfile: "tool_dialog";
        readonly verifiedOperations: readonly ["chat", "tool_roundtrip"];
        readonly streamingVerified: true;
        readonly cancellationVerified: true;
        readonly textInputOutputVerified: true;
        readonly toolDefinitionsSupported: true;
        readonly toolChoiceSupported: true;
        readonly toolResultContinuationSupported: true;
        readonly permitsConversationReady: true;
        readonly toolRoundtripConformanceDigest: string;
      }
  );

type RequiredCapabilityForSlot<S extends SupplySlotId> = S extends "dialog"
  ? CapabilityReceipt
  : S extends "thinking"
    ? CapabilityReceipt & {
        readonly reasoningSupport: Extract<
          CapabilityReasoningSupportV2,
          { readonly kind: "native_reasoning" | "verified_deliberative_decomposition" }
        >;
      }
    : S extends "cheap"
      ? CapabilityReceipt & {
          readonly marginalSpendClass: Extract<
            CapabilityMarginalSpendClassV2,
            { readonly kind: "owned_capacity" | "verified_low_cost" }
          >;
        }
      : CapabilityReceipt & {
          readonly structuredOutputSupport: Extract<
            CapabilityStructuredOutputSupportV2,
            { readonly kind: "json_schema_strict" }
          >;
          readonly observedModelIdentityDigest: string;
        };

