type FallbackTerminalCursorReceipt<K extends SupplySlotId = SupplySlotId> = {
  [S in K]: FallbackSequenceCursorBase<S> &
    (
    | {
        readonly cursorCause: "solution_terminal";
        readonly state: "terminal";
        readonly predecessorCursor: FallbackSolutionInFlightCursorReceipt<S>;
        readonly lastSolutionAttemptLease: FallbackSolutionAttemptLeaseReceipt<S>;
        readonly lastSolutionTerminal: FallbackSolutionTerminalReceipt<S> & { readonly resultingFallbackCursorState: "terminal" };
        readonly zeroSolutionTerminal?: never;
      }
    | {
        readonly cursorCause: "zero_solution_terminal";
        readonly state: "terminal";
        readonly predecessorCursor: Extract<FallbackReadyCursorReceipt<S>, { readonly cursorCause: "initial" }>;
        readonly lastSolutionAttemptLease?: never;
        readonly lastSolutionTerminal?: never;
        readonly zeroSolutionTerminal: FallbackZeroSolutionTerminalReceipt<S>;
      }
    );
}[K];

type FallbackSequenceCursorReceipt<K extends SupplySlotId = SupplySlotId> = {
  [S in K]:
    | FallbackReadyCursorReceipt<S>
    | FallbackSolutionInFlightCursorReceipt<S>
    | FallbackTerminalCursorReceipt<S>;
}[K];

