type ExecutionPhysicalRequestTerminalReceipt<
  P extends ExecutionPhysicalRetrySafetySubjectV8 = ExecutionPhysicalRetrySafetySubjectV8,
> = ReceiptRef &
  ExecutionPhysicalRequestTerminalBase &
  (
    | {
        readonly intentState: "present";
        readonly sendIntent: ExecutionPhysicalSendIntentReceipt;
        readonly preIntentClosure?: never;
        readonly provesSendIntentLeaseAndPredecessorLastLeaseEqual: true;
      }
    | {
        readonly intentState: "absent";
        readonly sendIntent?: never;
        readonly preIntentClosure: PreIntentLeaseClosureReceipt<ExecutionPhysicalRequestLeaseReceipt>;
        readonly provesNoSendIntentNetworkOrProcessInputByteExistsForPhysicalRequestLease: true;
      }
  ) &
  (
    | {
        readonly intentState: "present";
        readonly outcome: "success";
        readonly sentState: "sent";
        readonly continuation: "await_registered_tool_results";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "success_with_registered_tools" }
        >;
        readonly registeredToolInvocationSet: RegisteredToolInvocationSetReceipt;
        readonly resultingCursorState: "awaiting_tool_results";
        readonly closesRequestCursor: false;
        readonly provesRegisteredToolSetEqualsExactResponseToolOccurrenceSet: true;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "success";
        readonly sentState: "sent";
        readonly continuation: "turn_complete";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "success_without_tools" }
        >;
        readonly registeredToolCallCount: 0;
        readonly registeredToolInvocationSet?: never;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
        readonly provesRawResponseContainsNoToolCallOccurrence: true;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "non_retryable_failure";
        readonly sentState: "sent";
        readonly continuation: "turn_complete";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "provider_failure" }
        >;
        readonly registeredToolCallCount: 0;
        readonly registeredToolInvocationSet?: never;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "retryable_failure";
        readonly sentState: "sent";
        readonly continuation: "advance";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "provider_failure" }
        >;
        readonly retrySafetySubject: Extract<P, { readonly outcome: "retryable_failure"; readonly continuation: "advance" }>;
        readonly automaticRetrySafety: ExecutionAutomaticRetrySafetyReceiptV8<
          Extract<P, { readonly outcome: "retryable_failure"; readonly continuation: "advance" }>
        >;
        readonly retryEdge: ExecutionAutomaticRetryAdvanceEdgeReceiptV8<
          Extract<P, { readonly outcome: "retryable_failure"; readonly continuation: "advance" }>
        >;
        readonly resultingCursorState: "ready";
        readonly closesRequestCursor: false;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "failed_before_send";
        readonly sentState: "not_sent";
        readonly continuation: "advance";
        readonly responseEvidence?: never;
        readonly retrySafetySubject: Extract<P, { readonly outcome: "failed_before_send"; readonly continuation: "advance" }>;
        readonly automaticRetrySafety: ExecutionAutomaticRetrySafetyReceiptV8<
          Extract<P, { readonly outcome: "failed_before_send"; readonly continuation: "advance" }>
        >;
        readonly retryEdge: ExecutionAutomaticRetryAdvanceEdgeReceiptV8<
          Extract<P, { readonly outcome: "failed_before_send"; readonly continuation: "advance" }>
        >;
        readonly resultingCursorState: "ready";
        readonly closesRequestCursor: false;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "retryable_failure";
        readonly sentState: "sent";
        readonly continuation: "exhausted";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "provider_failure" }
        >;
        readonly retrySafetySubject: Extract<P, { readonly outcome: "retryable_failure"; readonly continuation: "exhausted" }>;
        readonly automaticRetrySafety: ExecutionAutomaticRetrySafetyReceiptV8<
          Extract<P, { readonly outcome: "retryable_failure"; readonly continuation: "exhausted" }>
        >;
        readonly exhaustionOrCancellationEvidence: ReceiptRef;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "failed_before_send" | "cancelled_before_send" | "hard_stopped_before_send" | "deadline_before_send";
        readonly sentState: "not_sent";
        readonly continuation: "exhausted" | "cancelled" | "hard_stopped" | "deadline";
        readonly responseEvidence?: never;
        readonly exhaustionOrCancellationEvidence: ReceiptRef;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
      }
    | {
        readonly intentState: "absent";
        readonly outcome:
          | "failed_before_intent"
          | "cancelled_before_intent"
          | "hard_stopped_before_intent"
          | "deadline_before_intent"
          | "lease_expired_before_intent"
          | "revoked_before_intent";
        readonly sentState: "not_sent";
        readonly continuation: "exhausted" | "cancelled" | "hard_stopped" | "deadline";
        readonly responseEvidence?: never;
        readonly exhaustionOrCancellationEvidence: ImportedOpaqueEvidenceLeafReceipt;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "cancelled_after_send" | "hard_stopped_after_send" | "deadline_after_send";
        readonly sentState: "sent";
        readonly continuation: "turn_complete";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "partial_transport_or_delivery_unknown" }
        >;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
      }
    | {
        readonly intentState: "present";
        readonly outcome: "delivery_unknown";
        readonly sentState: "delivery_unknown";
        readonly continuation: "terminal";
        readonly responseEvidence: Extract<
          ExecutionResponseEvidenceReceipt,
          { readonly responseClass: "partial_transport_or_delivery_unknown" }
        >;
        readonly automaticRetryAndFallbackForbidden: true;
        readonly authoritativeDeliveryReconciliationRequiredBeforeAnyNewRequest: true;
        readonly resultingCursorState: "terminal";
        readonly closesRequestCursor: true;
      }
  ) &
  (
    | { readonly billingDisposition: "not_sent_no_charge"; readonly sentState: "not_sent"; readonly billingTerminalRefs: readonly [] }
    | { readonly billingDisposition: "settled"; readonly sentState: "sent"; readonly billingTerminalRefs: NonEmptyReadonly<ReceiptRef> }
    | {
        readonly billingDisposition: "charge_unknown";
        readonly sentState: "sent";
        readonly billingTerminalRefs: NonEmptyReadonly<ReceiptRef>;
      }
    | {
        readonly billingDisposition: "possibly_sent_charge_unknown_hold_retained";
        readonly sentState: "delivery_unknown";
        readonly billingTerminalRefs: NonEmptyReadonly<ReceiptRef>;
      }
  );

