type ExecutionProtocolImplementationReceiptV6 =
  | BundledOrDeclarativeExecutionProtocolImplementationReceipt
  | ThirdPartyExecutionProtocolImplementationReceipt;

type ExecutionActivationManifestForImplementationV6<
  I extends ExecutionProtocolImplementationReceiptV6,
> = I extends ThirdPartyExecutionProtocolImplementationReceipt
  ? ExecutionActivationManifestBase & {
      readonly protocolImplementation: I;
      readonly executionPluginActivationClosure: ExecutionThirdPartyPluginActivationClosureV6<I>;
      readonly driverArtifact: I["executionPluginPolicy"]["adapterArtifact"];
      readonly driverProvenance: I["executionPluginPolicy"]["buildProvenance"];
      readonly driverVerifiedOpenHandle: I["executionPluginPolicy"]["adapterArtifact"]["verifiedOpenHandle"];
      readonly executionPluginUserDecisionConsumptionCommit: I["executionPluginPolicy"]["userDecisionConsumptionCommit"];
      readonly provesDriverArtifactProvenanceOpenHandleAndConsentAreExactProjectionsOfTheSameActivationClosure: true;
    }
  : I extends BundledOrDeclarativeExecutionProtocolImplementationReceipt
    ? ExecutionActivationManifestBase & {
        readonly protocolImplementation: I;
        readonly executionPluginActivationClosure: Extract<
          ExecutionPluginActivationClosureV6,
          { readonly pluginMode: "not_applicable_bundled_or_declarative" }
        > & { readonly protocolImplementation: I };
      }
    : never;

type ExecutionActivationManifest = ExecutionActivationManifestForImplementationV6<
  ExecutionProtocolImplementationReceiptV6
>;

type ActivationManifest = InferenceActivationManifest | ExecutionActivationManifest;

